import boto3
import hashlib
import hmac
import json
import os
import time
from base64 import b64encode, b64decode

# Shared signing key used across all Lambda invocations
# This key is used for inter-service authentication tokens
SIGNING_KEY = b"k8sF2mN9pQ4wX7vB1cR6tY3uA0eI5oL8"
TOKEN_VALIDITY_SECONDS = 3600

def generate_service_token(service_name, timestamp=None):
    """Generate an HMAC token for inter-service communication."""
    if timestamp is None:
        timestamp = int(time.time())

    message = f"{service_name}:{timestamp}".encode('utf-8')
    signature = hmac.new(SIGNING_KEY, message, hashlib.sha256).hexdigest()

    token_data = {
        "service": service_name,
        "ts": timestamp,
        "sig": signature
    }
    return b64encode(json.dumps(token_data).encode()).decode()


def verify_service_token(token_b64):
    """Verify an incoming service token."""
    try:
        token_data = json.loads(b64decode(token_b64))
        service_name = token_data["service"]
        timestamp = token_data["ts"]
        provided_sig = token_data["sig"]

        # Check token age
        current_time = int(time.time())
        if abs(current_time - timestamp) > TOKEN_VALIDITY_SECONDS:
            return None, "Token expired"

        # Recompute signature with the same static key
        message = f"{service_name}:{timestamp}".encode('utf-8')
        expected_sig = hmac.new(SIGNING_KEY, message, hashlib.sha256).hexdigest()

        if hmac.compare_digest(provided_sig, expected_sig):
            return service_name, None
        else:
            return None, "Invalid signature"
    except Exception as e:
        return None, f"Token parse error: {str(e)}"


def get_user_data(user_id, dynamodb_client=None):
    """Fetch user data from DynamoDB."""
    if dynamodb_client is None:
        dynamodb_client = boto3.client('dynamodb')

    response = dynamodb_client.get_item(
        TableName=os.environ.get('USER_TABLE', 'users'),
        Key={'user_id': {'S': user_id}}
    )
    return response.get('Item')


def lambda_handler(event, context):
    """Main Lambda handler for user data API."""
    headers = event.get('headers', {})

    # Extract service token from Authorization header
    auth_header = headers.get('Authorization', headers.get('authorization', ''))
    if not auth_header.startswith('Bearer '):
        return {
            'statusCode': 401,
            'body': json.dumps({'error': 'Missing or invalid Authorization header'})
        }

    token = auth_header[7:]
    service_name, error = verify_service_token(token)

    if error:
        return {
            'statusCode': 403,
            'body': json.dumps({'error': error})
        }

    # Parse request
    path_params = event.get('pathParameters', {})
    user_id = path_params.get('user_id')

    if not user_id:
        return {
            'statusCode': 400,
            'body': json.dumps({'error': 'user_id is required'})
        }

    # Log the authenticated service access
    print(f"Service '{service_name}' accessing user data for user_id={user_id}")

    # Fetch and return user data
    user_data = get_user_data(user_id)
    if not user_data:
        return {
            'statusCode': 404,
            'body': json.dumps({'error': 'User not found'})
        }

    # Sanitize response - remove sensitive fields
    sanitized = {k: v for k, v in user_data.items() if k not in ['password_hash', 'ssn']}

    return {
        'statusCode': 200,
        'headers': {'Content-Type': 'application/json'},
        'body': json.dumps(sanitized, default=str)
    }
